from pathlib import Path
R=Path(__file__).resolve().parent;stage=sys.argv[1] if len(sys.argv)>1 else 'all';read=lambda p:json.loads(p.read_text());a=read(R/f'audit_{stage}.json');notes=read(R/'adjudication_notes.json');inspected=set(read(R/'reviewed_ids.json'));out={}
reasons={'E01':'Missing Session-to-merge_setting request argument binding/wire context; conditional local filter behavior alone does not close introduced public-header observation.','E02':'Public malformed URL requirement and prepare_url validator. Do not assume missing public-call dispatch or parsed host result as factual API output.','E03':'Visible binary-body reproduction and bytes conversion establish the target decoding error; no additional remote network behavior is inferred.','E04':'Byte-method decoding versus Python3 bytes-repr conversion, using public reproduction and visible helper. Missing imports do not prove unbound names.','E05':'EncodedFile descriptor/delegation and fixed rb+ mode establish wrapper mode contract and the supplied text/bytes writer path.','E06':'Native FD capture initialization and TextIOWrapper newline setting establish fixed CR translation behavior at the capture boundary.','E07':'Public phase-list consistency contract, actual clear/reset bodies and unchanged versus replaced list identity.','E08':'Public single-set_level two-test sequence and visible restoration code establish the target handler-level leak.','E10':'Named Contains.as_set direct API contract and return-set versus NotImplementedError body. No Piecewise completion is claimed without its source.','E11':'Public working flat cls=Function API and failing nested iterable input, together with recursive keyword retention/loss. Do not infer unrelated Function implementations.','E12':'Public sum traceback and visible _check_vector establish rejection of sum integer start0. The separate0*N.x is a zero Vector, not that scalar.'}
for x in a['rows']:
 rid=x['run_id'];assert rid in inspected,rid;v=x['review'];idx=list(range(len(v['issues']))) if v else [];supported=idx;extra=[];verdict=v is not None and v['status']!='insufficient_evidence';reason=reasons[x['case_id']]
 if rid in notes:
  note=notes[rid];extra=note['unsupported_issue_indices'];supported=[i for i in idx if i not in extra];verdict=note['verdict_supported'];reason=note['reason']
 out[rid]={'supported_issue_indices':supported,'unsupported_issue_indices':extra,'verdict_supported':verdict,'reason':reason,'author_visible':True,'operational_valid':x['status']=='ok' and not x['errors']}
